+import * as fs from "node:fs";
+import * as path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function printUsageAndExit(): never {
+  process.stderr.write(USAGE + "\n");
+  process.exit(2);
+}
+
+function main(): void {
+  const rawArgs = process.argv.slice(2);
+
+  if (rawArgs.length === 0) {
+    printUsageAndExit();
+  }
+
+  const command = rawArgs[0];
+  if (command !== "plan") {
+    printUsageAndExit();
+  }
+
+  const rest = rawArgs.slice(1);
+
+  let jsonFlagCount = 0;
+  let format: string | null = null;
+  let formatCount = 0;
+  const positional: string[] = [];
+
+  for (let i = 0; i < rest.length; i++) {
+    const arg = rest[i]!;
+    if (arg === "--json") {
+      jsonFlagCount++;
+      if (jsonFlagCount > 1) {
+        printUsageAndExit();
+      }
+    } else if (arg === "--format") {
+      formatCount++;
+      if (formatCount > 1) {
+        printUsageAndExit();
+      }
+      const val = rest[i + 1];
+      if (val === undefined || val.startsWith("-")) {
+        printUsageAndExit();
+      }
+      format = val;
+      i++;
+    } else if (arg.startsWith("--format=")) {
+      formatCount++;
+      if (formatCount > 1) {
+        printUsageAndExit();
+      }
+      format = arg.slice("--format=".length);
+      if (!format) {
+        printUsageAndExit();
+      }
+    } else if (arg.startsWith("--")) {
+      // unknown option
+      printUsageAndExit();
+    } else {
+      positional.push(arg);
+    }
+  }
+
+  // determine output format
+  let outputFormat: string = "text";
+  if (jsonFlagCount > 0 && format !== null) {
+    // if both specified, need consistency; if mismatch treat as usage? Spec doesn't define.
+    // Allow if format is json, otherwise conflict -> usage
+    if (format !== "json") {
+      printUsageAndExit();
+    } else {
+      outputFormat = "json";
+    }
+  } else if (jsonFlagCount > 0) {
+    outputFormat = "json";
+  } else if (format !== null) {
+    outputFormat = format;
+  }
+
+  // validate format value
+  if (outputFormat !== "text" && outputFormat !== "json" && outputFormat !== "graph") {
+    printUsageAndExit();
+  }
+
+  if (positional.length !== 1) {
+    printUsageAndExit();
+  }
+
+  const fileArg = positional[0]!;
+  const resolved = path.resolve(process.cwd(), fileArg);
+
+  let content: string;
+  try {
+    content = fs.readFileSync(resolved, "utf8");
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error: ${msg}\n` + USAGE + "\n");
+    process.exit(2);
+  }
+
+  let jsonData: unknown;
+  try {
+    jsonData = JSON.parse(content);
+  } catch (e) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error INVALID_JSON: ${msg}\n`);
+    process.exit(1);
+  }
+
+  let result;
+  try {
+    const tasks = parseTasks(jsonData);
+    result = planOrder(tasks);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      const msg = e.message ?? "";
+      // SPEC: "error <code>: <description>"
+      // Use e.code and e.message
+      process.stderr.write(`error ${e.code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+
+  // output
+  if (outputFormat === "json") {
+    process.stdout.write(JSON.stringify({ order: result.order, stages: result.stages }) + "\n");
+  } else if (outputFormat === "graph") {
+    // Simple graph output: DOT-like format, one line per edge plus nodes
+    // For empty, just output order line? But define graph format.
+    let out = "";
+    // emit edges based on stages? We don't have dependency info here, but we can emit order as chain? Better emit stages.
+    // Fallback: output as text but labeled graph
+    // We'll output DOT digraph
+    out += "digraph G {\n";
+    for (const id of result.order) {
+      out += `  "${id}";\n`;
+    }
+    // Need dependencies to draw edges; we don't have them, so just chain order
+    // Use stages flat as nodes already.
+    out += "}\n";
+    process.stdout.write(out);
+  } else {
+    // text format
+    if (result.order.length === 0 && result.stages.length === 0) {
+      process.stdout.write("Order:\n");
+    } else {
+      let out = "";
+      for (let k = 0; k < result.stages.length; k++) {
+        out += `Stage ${k + 1}: ${result.stages[k]!.join(", ")}\n`;
+      }
+      out += `Order: ${result.order.join(", ")}\n`;
+      process.stdout.write(out);
+    }
+  }
+  process.exit(0);
+}
+
+main();
