+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks. */
+export interface PlanResult {
+  /** Every task id in execution order. */
+  order: string[];
+  /** Tasks grouped by earliest round they can run. */
+  stages: string[][];
+}
+
+/**
+ * Plans execution order and stages for the given tasks.
+ *
+ * @param tasks - tasks in the shape returned by parseTasks
+ * @returns order and stages as defined in SPEC.md
+ * @throws DuplicateTaskError when duplicate ids exist
+ * @throws UnknownDependencyError when a dependency is missing
+ * @throws CycleError when a dependency cycle exists
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  if (tasks.length === 0) {
+    return { order: [], stages: [] };
+  }
+
+  // R3.1 duplicate ids
+  const count = new Map<string, number>();
+  const firstPos = new Map<string, number>();
+  for (let i = 0; i < tasks.length; i++) {
+    const id = tasks[i]!.id;
+    count.set(id, (count.get(id) ?? 0) + 1);
+    if (!firstPos.has(id)) firstPos.set(id, i);
+  }
+  const duplicates: string[] = [];
+  for (const [id, c] of count) {
+    if (c > 1) duplicates.push(id);
+  }
+  if (duplicates.length > 0) {
+    duplicates.sort((a, b) => (firstPos.get(a) ?? 0) - (firstPos.get(b) ?? 0));
+    throw new DuplicateTaskError(duplicates);
+  }
+
+  // R3.2 unknown dependency
+  const idSet = new Set<string>(tasks.map((t) => t.id));
+  for (let i = 0; i < tasks.length; i++) {
+    const t = tasks[i]!;
+    for (let j = 0; j < t.dependsOn.length; j++) {
+      const dep = t.dependsOn[j]!;
+      if (!idSet.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build structures
+  const n = tasks.length;
+  const idToIndex = new Map<string, number>();
+  const priorityById = new Map<string, number>();
+  const inputPosById = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    idToIndex.set(t.id, i);
+    priorityById.set(t.id, t.priority);
+    inputPosById.set(t.id, i);
+  }
+
+  // dedup dependencies per task
+  const depsById = new Map<string, string[]>();
+  const dependents = new Map<string, string[]>();
+  const indegree = new Map<string, number>();
+  for (const t of tasks) {
+    const uniq = [...new Set(t.dependsOn)];
+    depsById.set(t.id, uniq);
+    indegree.set(t.id, uniq.length);
+    for (const d of uniq) {
+      const arr = dependents.get(d);
+      if (arr) arr.push(t.id);
+      else dependents.set(d, [t.id]);
+    }
+  }
+
+  // Kahn with priority tie-breaker
+  const ready: string[] = [];
+  for (const t of tasks) {
+    if ((indegree.get(t.id) ?? 0) === 0) ready.push(t.id);
+  }
+
+  const order: string[] = [];
+  const round = new Map<string, number>();
+
+  // helper to pick best from ready
+  function pickBest(): number {
+    let bestIdx = 0;
+    let bestPriority = priorityById.get(ready[0]!) ?? 0;
+    let bestPos = inputPosById.get(ready[0]!) ?? 0;
+    for (let i = 1; i < ready.length; i++) {
+      const id = ready[i]!;
+      const p = priorityById.get(id) ?? 0;
+      const pos = inputPosById.get(id) ?? 0;
+      if (p > bestPriority || (p === bestPriority && pos < bestPos)) {
+        bestIdx = i;
+        bestPriority = p;
+        bestPos = pos;
+      }
+    }
+    return bestIdx;
+  }
+
+  while (ready.length > 0) {
+    const bestIdx = pickBest();
+    const id = ready.splice(bestIdx, 1)[0]!;
+    // compute round
+    const deps = depsById.get(id) ?? [];
+    let r = 0;
+    if (deps.length > 0) {
+      let max = -1;
+      for (const d of deps) {
+        const rd = round.get(d) ?? 0;
+        if (rd > max) max = rd;
+      }
+      r = max + 1;
+    }
+    round.set(id, r);
+    order.push(id);
+
+    const ds = dependents.get(id) ?? [];
+    for (const depId of ds) {
+      const cur = (indegree.get(depId) ?? 0) - 1;
+      indegree.set(depId, cur);
+      if (cur === 0) ready.push(depId);
+    }
+  }
+
+  if (order.length !== n) {
+    // cycle: find a cycle among remaining nodes
+    const remaining = new Set<string>();
+    for (const t of tasks) {
+      if (!round.has(t.id) && (indegree.get(t.id) ?? 0) > 0) {
+        // node not processed (indegree >0) - includes nodes not yet ready
+        // But nodes that are ready but not picked would have been in ready; if order stopped early, ready is empty, so all unprocessed have indegree>0
+        remaining.add(t.id);
+      } else if (!order.includes(t.id)) {
+        // fallback: any not in order (covers case where indegree 0 but ready empty shouldn't happen)
+        // Actually order length != n means some nodes remain with indegree>0
+        // Include them
+        if (!round.has(t.id)) remaining.add(t.id);
+      }
+    }
+    // In case remaining empty due to logic, collect all not in order
+    if (remaining.size === 0) {
+      for (const t of tasks) if (!order.includes(t.id)) remaining.add(t.id);
+    }
+
+    // Build adjacency for remaining, only edges to remaining
+    const adj = new Map<string, string[]>();
+    for (const id of remaining) {
+      const deps = depsById.get(id) ?? [];
+      adj.set(id, deps.filter((d) => remaining.has(d)));
+    }
+
+    const color = new Map<string, number>(); // 0 unvisited,1 visiting,2 done
+    for (const id of remaining) color.set(id, 0);
+    const parent = new Map<string, string>();
+
+    let foundCycle: string[] | null = null;
+
+    for (const start of remaining) {
+      if (foundCycle) break;
+      if ((color.get(start) ?? 0) !== 0) continue;
+      const stack: { id: string; nextIdx: number }[] = [{ id: start, nextIdx: 0 }];
+      while (stack.length > 0 && !foundCycle) {
+        const frame = stack[stack.length - 1]!;
+        const curId = frame.id;
+        if ((color.get(curId) ?? 0) === 0) color.set(curId, 1);
+        const neigh = adj.get(curId) ?? [];
+        if (frame.nextIdx < neigh.length) {
+          const nb = neigh[frame.nextIdx++]!;
+          const c = color.get(nb) ?? 0;
+          if (c === 0) {
+            parent.set(nb, curId);
+            stack.push({ id: nb, nextIdx: 0 });
+          } else if (c === 1) {
+            // cycle found nb ancestor of curId
+            const path: string[] = [];
+            let cur: string | undefined = curId;
+            path.push(cur);
+            while (cur !== nb && cur !== undefined) {
+              cur = parent.get(cur);
+              if (cur !== undefined) path.push(cur);
+            }
+            // path is [curId, ..., nb]
+            path.reverse(); // now [nb, ..., curId]
+            path.push(nb); // close
+            foundCycle = path;
+            break;
+          } else {
+            // done, ignore
+          }
+        } else {
+          color.set(curId, 2);
+          stack.pop();
+        }
+      }
+    }
+
+    if (!foundCycle) {
+      // Fallback for self-loop not caught? Should be caught above.
+      // Try to find self-loop directly
+      for (const id of remaining) {
+        const deps = depsById.get(id) ?? [];
+        if (deps.includes(id)) {
+          foundCycle = [id, id];
+          break;
+        }
+      }
+    }
+    if (!foundCycle) {
+      // As last resort create generic cycle with remaining nodes
+      const first = remaining.values().next().value as string;
+      foundCycle = [first, first];
+    }
+    throw new CycleError(foundCycle);
+  }
+
+  // Build stages from round
+  let maxRound = -1;
+  for (const v of round.values()) if (v > maxRound) maxRound = v;
+  if (maxRound < 0) return { order, stages: [] };
+  const stages: string[][] = Array.from({ length: maxRound + 1 }, () => []);
+  for (const t of tasks) {
+    const r = round.get(t.id) ?? 0;
+    stages[r]!.push(t.id);
+  }
+  for (let k = 0; k < stages.length; k++) {
+    const arr = stages[k]!;
+    arr.sort((a, b) => {
+      const pa = priorityById.get(a) ?? 0;
+      const pb = priorityById.get(b) ?? 0;
+      if (pa !== pb) return pb - pa;
+      return (inputPosById.get(a) ?? 0) - (inputPosById.get(b) ?? 0);
+    });
+  }
+
+  return { order, stages };
+}
